<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;class Payment extends Model {const STATUS_CREATED='created',STATUS_INITIALIZED='initialized',STATUS_SUCCESS='success',STATUS_FAILED='failed',STATUS_REVIEW='review';protected $fillable=['order_id','provider','reference','provider_transaction_id','amount_minor','currency','status','access_code','authorization_url','channel','gateway_response','paid_at','verified_at'];protected $casts=['amount_minor'=>'integer','paid_at'=>'datetime','verified_at'=>'datetime'];public function order():BelongsTo{return $this->belongsTo(Order::class);}}